var MARKER='mx2_level_placement_v1';
function copy(x){return JSON.parse(JSON.stringify(x));}
function own(o,k){return Object.prototype.hasOwnProperty.call(o,k);}
function all(book){return (book.deck||[]).concat(book.archived||[]);}
function hits(w,book,faculty){return (DATA.words[w]||[]).filter(function(h){var d=DATA.docs[h.doc];return d.book===book&&(faculty==null||d.faculty===faculty);});}
function evidence(it,book){var h=hits(it.w,book,it.g);if(!h.length)throw new Error('Missing faculty evidence: '+book+'/'+it.g+'/'+it.w);it.fc=h.length;it.cnt=hits(it.w,book).length;it.examDocs=h.map(function(x){return x.doc;});delete it.cntLabel;return it;}
function apply(books){
  var by={},moves={},original={};books.forEach(function(b){by[b.id]=b;});
  if(!by.base||!by.plus||!by.waseda||!by.keio)return;
  if(by.base.placementVersion===DATA.version)return;
  books.forEach(function(b){original[b.id]={deck:b.deck.slice(),sections:b.sections.map(function(s){return {name:s.name,arr:s.arr.slice()};}),hw:b.hw,sub:b.sub};b.archived=[];b.placementVersion=DATA.version;});
  DATA.moves.forEach(function(m){moves[m.w]=m;});
  ['waseda','keio'].forEach(function(id){var b=by[id];b.sub=id==='waseda'?'早稲田英単語':'慶應英単語';b.examRecords=b.deck.filter(function(x){return x.g;});b.examRecords.forEach(function(x){evidence(x,id);x.studyBook=moves[x.w]&&moves[x.w].to[0]==='base'?'base':id;});});
  DATA.moves.forEach(function(m){
    var src=by[m.from[0]].deck.find(function(x){return !x.drv&&x.w===m.w;});if(!src)throw new Error('Missing moved word: '+m.w);
    m.to.forEach(function(id){var b=by[id];
      if(id==='base'){
        if(!b.deck.some(function(x){return x.w===m.w;})){var x=copy(src);['id','g','cnt','fc','cntLabel','sourceEvidence','examDocs','d'].forEach(function(k){delete x[k];});x.lv=5;x.studyBook='base';b.deck.push(x);var sec=b.sections.find(function(s){return s.name==='基礎・標準の補充';});if(!sec){sec={name:'基礎・標準の補充',arr:[]};b.sections.push(sec);}sec.arr.push(x);}
      }else{
        var faculties=[];hits(m.w,id).forEach(function(h){var g=DATA.docs[h.doc].faculty;if(faculties.indexOf(g)<0)faculties.push(g);});
        if(!faculties.length)throw new Error('Unverified university: '+id+'/'+m.w);
        faculties.forEach(function(g){var x=copy(src);delete x.d;delete x.img;delete x.ex;x.g=g;x.id='sx1:'+id+':'+encodeURIComponent(g)+':'+encodeURIComponent(m.w.toLowerCase());x.studyBook=id;evidence(x,id);var fp=(((root.SOKEI_IMAGES||{})[id]||{})[g]||{})[m.w];if(fp)x.img=fp;b.deck.push(x);b.examRecords.push(x);var sec=b.sections.find(function(s){return s.name===g;});if(!sec){sec={name:g,arr:[]};b.sections.push(sec);}sec.arr.push(x);});
      }
    });
    m.from.forEach(function(id){var b=by[id];b.deck=b.deck.filter(function(x){if(x.w!==m.w||x.drv)return true;b.archived.push(x);return false;});b.sections.forEach(function(s){s.arr=s.arr.filter(function(x){return x.w!==m.w||x.drv;});});});
  });
  books.forEach(function(b){var seen={};b.hw=0;b.deck.forEach(function(x){
    // A derivative whose parent moved must remain reachable by the regular study queue.
    // Keep it at the source book as an independent entry; do not infer exam evidence for it.
    var parent=moves[x.parentWord];if(x.drv&&parent&&parent.from.indexOf(b.id)>=0){x.wasDerivative=1;delete x.drv;}
    if(!x.drv&&!seen[x.w]){seen[x.w]=1;b.hw++;}
  });});
  return function restore(){books.forEach(function(b){var o=original[b.id];if(!o)return;var users=b.deck.filter(function(x){return x.user;});b.deck=o.deck.concat(users);b.deck.forEach(function(x){if(x.wasDerivative){x.drv=1;delete x.wasDerivative;}});b.sections=o.sections;if(users.length)b.sections.push({name:'あなたの追加単語',arr:users});b.hw=o.hw;b.sub=o.sub;b.archived=[];delete b.placementVersion;});};
}
// Copy progress once, retaining the source and any existing destination progress.
// The existing write-ahead journal makes all destination keys + marker one transaction.
function migrate(books,storage,transaction){
  if(storage.getItem(MARKER)===DATA.version)return false;
  var snapshot={},changes={},by={};books.forEach(function(b){by[b.id]=b;});
  function read(id,p){var k='mx2_'+p+'_'+id;if(!own(snapshot,k)){var raw=storage.getItem(k);var v=raw==null?(['miss','rev'].indexOf(p)>=0?[]:{}):JSON.parse(raw);if(!v||typeof v!=='object'||Array.isArray(v)!==(['miss','rev'].indexOf(p)>=0))throw new Error('Invalid saved progress: '+k);snapshot[k]=v;}return snapshot[k];}
  DATA.moves.forEach(function(m){m.to.forEach(function(dest){
    var target=by[dest].deck.find(function(x){return x.w===m.w;});
    // Each word uses one coherent source snapshot. Prefer a source with an unresolved weakness,
    // then one with learning history. The other university's records remain stored at source.
    var source=m.from.slice().sort(function(a,b){function rank(id){var s=read(id,'wst')[m.w];return s==='weak'?4:s==='review'?3:own(read(id,'fc'),m.w)?2:s==='learned'?1:0;}return rank(b)-rank(a);})[0];
    ['wst','fc','whist','munk'].forEach(function(p){var dst=read(dest,p),src=read(source,p);if(own(dst,m.w)||!own(src,m.w))return;var value=copy(src[m.w]);
      if(p==='munk'&&Array.isArray(value)){var old=all(by[source]).find(function(x){return x.w===m.w;});var before=old.ms||[old.m],after=target.ms||[target.m];value=value.map(function(i){return after.indexOf(before[i]);}).filter(function(i){return i>=0;});}
      dst[m.w]=value;changes['mx2_'+p+'_'+dest]=JSON.stringify(dst);
    });
    ['miss','rev'].forEach(function(p){var dst=read(dest,p),src=read(source,p),key=function(x){return typeof x==='string'?x:x.w;};if(dst.some(function(x){return key(x)===m.w;}))return;src.filter(function(x){return key(x)===m.w;}).forEach(function(x){dst.push(copy(x));changes['mx2_'+p+'_'+dest]=JSON.stringify(dst);});});
  });});
  changes[MARKER]=DATA.version;transaction.write(storage,changes);return true;
}
root.EitanLevelPlacement={version:DATA.version,marker:MARKER,data:DATA,all:all,hits:hits,apply:apply,migrate:migrate};

